WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY shipping_fee DESC, id) AS rank_in_group FROM orders) t WHERE rank_in_group = 1) SELECT CASE WHEN amount >= 1360 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, channel, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, SUM(shipping_fee) FILTER (WHERE channel = 'mobile') AS mobile_total_shipping_fee, SIZE(COLLECT_SET(channel)) AS num_channels FROM ranked GROUP BY 1, 2 HAVING mobile_total_shipping_fee > 0 ORDER BY amount_tier DESC;
